gcWC(){return"\u0634\u062e\u0635 \u062d\u0642\u06cc\u0642\u06cc"},
gcWB(){return"\u0634\u062e\u0635 \u062d\u0642\u0648\u0642\u06cc"},
gcWs(){return"\u06a9\u062f \u0645\u0644\u06cc (\u06f1\u06f0 \u0631\u0642\u0645)"},
