gcWw(){return"\u0646\u0627\u0645 \u0648 \u0646\u0627\u0645 \u062e\u0627\u0646\u0648\u0627\u062f\u06af\u06cc"},
gcWk(){return"\u0646\u0627\u0645 \u0641\u0627\u0631\u0633\u06cc \u0634\u0631\u06a9\u062a"},
gcUZ(){return"CSR \u0633\u0627\u062e\u062a\u0647 \u0646\u0634\u062f. \u0646\u0648\u0639 \u0645\u0648\u062f\u06cc \u0648 \u0627\u0637\u0644\u0627\u0639\u0627\u062a \u0647\u0648\u06cc\u062a\u06cc \u0631\u0627 \u0628\u0631\u0631\u0633\u06cc \u06a9\u0646\u06cc\u062f."},
